param([ValidateSet('x86', 'x64')][string]$CompileArchitecture)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
$testDir = Join-Path $repoRoot '.deps/adapter-test'
New-Item -ItemType Directory -Force $testDir | Out-Null
if ($CompileArchitecture) {
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
  Push-Location $testDir
  try {
    & cl.exe /nologo /std:c++17 /EHsc /W4 /WX "/I$source/bridge/src/util" "$repoRoot/tests/adapter_information.cpp" "/Fe:adapter-test-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw "Adapter test compilation failed for $CompileArchitecture" }
  } finally { Pop-Location }
} else {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileArchitecture $arch
    if ($LASTEXITCODE -ne 0) { throw "Adapter test compilation failed for $arch" }
    & (Join-Path $testDir "adapter-test-$arch.exe") write (Join-Path $testDir $arch)
    if ($LASTEXITCODE -ne 0) { throw "Native adapter payload write failed for $arch" }
  }
  foreach ($reader in @('x86', 'x64')) {
    foreach ($writer in @('x86', 'x64')) {
      & (Join-Path $testDir "adapter-test-$reader.exe") read (Join-Path $testDir $writer)
      if ($LASTEXITCODE -ne 0) { throw "Adapter transport test failed: $writer -> $reader" }
    }
  }
}
